/* =====================================================================
   Steve's Financial Report Dashboard — PROD prerequisite (DB)
   Create + seed  Workbench.dbo.ProposalOriginalRep  (attribution overrides)

   The dashboard LEFT JOINs this table on ProposalID and COALESCEs the original
   seller over the current rep. Missing table => runtime error; missing/partial
   rows => silently wrong CFO attribution. So this script is fail-closed + atomic.

   Hardened per crew review (Kimi K3 / Gemini 3.1 Pro / gpt-5.6-sol), 2026-07-21:
     - SET XACT_ABORT ON + single transaction  -> no partial seed
     - THROW (not RAISERROR) on precondition/asserts -> deploy stops on failure
     - UNIQUE index on ProposalID -> no double-count via the LEFT JOIN
     - hard row-count assert (563) -> truncation/transit loss fails the deploy
     - backs up any pre-existing prod table before reseeding (rollback)
     - dropped 1 bad override (ProposalID 396441, OrigRepName 'UNDEFINED') that
       would have EXCLUDED that proposal from the dashboard. 564 -> 563 clean rows.

   ProposalIDs are shared identity with prod (play is a ~24h replica of prod).
   Requires: the Workbench DB on prod (already used by the V1.5 SalesGoal deploy)
   AND that the GSTS ColdFusion datasource login can SELECT this table (see STEP 4).
   ===================================================================== */
SET NOCOUNT ON;
SET XACT_ABORT ON;   -- any error aborts the batch and rolls back the open transaction

-- STEP 0: preconditions (fail closed) ---------------------------------
IF DB_ID('Workbench') IS NULL
  THROW 50001, 'Workbench database not found on this server — it is required (used by the V1.5 dashboards).', 1;
GO
USE Workbench;
GO

-- STEP 1: backup any pre-existing table (one-time; preserves original for rollback)
IF OBJECT_ID('dbo.ProposalOriginalRep') IS NOT NULL
   AND OBJECT_ID('dbo.ProposalOriginalRep_bak_predeploy') IS NULL
BEGIN
  SELECT * INTO dbo.ProposalOriginalRep_bak_predeploy FROM dbo.ProposalOriginalRep;
END;
GO

-- STEP 2: create table + UNIQUE index if missing
IF OBJECT_ID('dbo.ProposalOriginalRep') IS NULL
  CREATE TABLE dbo.ProposalOriginalRep (
    ProposalID  int          NOT NULL,
    CurRepID    int          NULL,
    OrigRepName varchar(101) NULL,
    Source      varchar(32)  NOT NULL,
    Conflict    int          NOT NULL
  );
GO
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name='ux_por_ProposalID' AND object_id=OBJECT_ID('dbo.ProposalOriginalRep'))
  CREATE UNIQUE NONCLUSTERED INDEX ux_por_ProposalID ON dbo.ProposalOriginalRep (ProposalID);
GO

-- STEP 3: atomic re-seed ---------------------------------------------
BEGIN TRANSACTION;
DELETE FROM dbo.ProposalOriginalRep;

-- hard assert: exactly 563 rows or the whole deploy rolls back
IF (SELECT COUNT(*) FROM dbo.ProposalOriginalRep) <> 563
  THROW 50002, 'Seed row count != 563 — rolling back (transit/truncation loss).', 1;

COMMIT TRANSACTION;
GO

/* STEP 4 (REQUIRED — Jordan/IT): the GSTS ColdFusion datasource login must be able to
   SELECT this table. On prod the CF login may be scoped to the gsts DB only; grant it:
       GRANT SELECT ON Workbench.dbo.ProposalOriginalRep TO [<GSTS_CF_DATASOURCE_LOGIN>];
   (Use the actual SQL login the prod GSTS datasource connects as. If that login is db_owner
    / sysadmin, this is already covered — confirm rather than assume.)                        */

-- final verify (expect 563)
SELECT COUNT(*) AS RowCount_expect_563 FROM dbo.ProposalOriginalRep;
